function order(tasks) {
  const waiting = new Map(Object.entries(tasks).map(([t, deps]) => [t, deps.length]));
  const queue = Object.keys(tasks).filter((t) => !tasks[t].length);
  const out = [];
  while (queue.length) {
    const t = queue.shift();
    out.push(t);
    for (const [u, deps] of Object.entries(tasks)) if (deps.includes(t)) { waiting.set(u, waiting.get(u) - 1); if (!waiting.get(u)) queue.push(u); }
  }
  return out.length === waiting.size ? out.join(', ') : 'cycle';
}

